CREATE OR REPLACE VIEW banking_dwh.gold.v_daily_transaction (
  transaction_date COMMENT 'Legacy: Date. CAST(TransactionDate AS DATE)',
  total_transactions COMMENT 'Legacy: TotalTransactions. COUNT(TransactionID)',
  total_amount COMMENT 'Legacy: TotalAmount. SUM(Amount)'
)
COMMENT 'Daily transaction volume and amount over all dates. Replaces sp_DailyTransaction (unfiltered).'
TBLPROPERTIES ('banking_dwh.layer' = 'gold', 'banking_dwh.owner_ticket' = '9')
AS
SELECT
  date_from_unix_date(CAST(floor(unix_seconds(transaction_date) / 86400) AS INT)) AS transaction_date,
  count(transaction_id) AS total_transactions,
  sum(amount) AS total_amount
FROM banking_dwh.silver.fact_transaction
GROUP BY date_from_unix_date(CAST(floor(unix_seconds(transaction_date) / 86400) AS INT));

CREATE OR REPLACE FUNCTION banking_dwh.gold.fn_daily_transaction(
  start_date DATE,
  end_date DATE
)
RETURNS TABLE (
  transaction_date DATE COMMENT 'Legacy: Date',
  total_transactions BIGINT COMMENT 'Legacy: TotalTransactions',
  total_amount DECIMAL(29,4) COMMENT 'Legacy: TotalAmount'
)
COMMENT 'Daily summary for an inclusive date range, ordered by date. Replaces sp_DailyTransaction @start_date, @end_date.'
RETURN
SELECT
  date_from_unix_date(CAST(floor(unix_seconds(transaction_date) / 86400) AS INT)) AS transaction_date,
  count(transaction_id) AS total_transactions,
  sum(amount) AS total_amount
FROM banking_dwh.silver.fact_transaction
WHERE date_from_unix_date(CAST(floor(unix_seconds(transaction_date) / 86400) AS INT)) BETWEEN fn_daily_transaction.start_date AND fn_daily_transaction.end_date
GROUP BY date_from_unix_date(CAST(floor(unix_seconds(transaction_date) / 86400) AS INT))
ORDER BY transaction_date;

CREATE OR REPLACE FUNCTION banking_dwh.gold.fn_balance_per_customer(
  customer_name STRING
)
RETURNS TABLE (
  customer_name STRING COMMENT 'Legacy: CustomerName',
  account_type STRING COMMENT 'Legacy: AccountType',
  initial_balance DECIMAL(19,4) COMMENT 'Legacy: InitialBalance. a.Balance',
  current_balance DECIMAL(20,4) COMMENT 'Legacy: CurrentBalance. Balance + coalesce(SUM(CASE Deposit +amt ELSE -amt), 0)'
)
COMMENT 'Current balance per active account for customers whose name contains the argument. Replaces sp_BalancePerCustomer @customer_name.'
RETURN
WITH transaction_summary AS (
  SELECT
    account_id,
    sum(CASE WHEN lower(rtrim(transaction_type)) = 'deposit' THEN amount ELSE -amount END) AS total_transaction_amount
  FROM banking_dwh.silver.fact_transaction
  GROUP BY account_id
)
SELECT
  c.customer_name,
  a.account_type,
  a.balance AS initial_balance,
  CAST(a.balance + coalesce(ts.total_transaction_amount, 0) AS DECIMAL(20,4)) AS current_balance
FROM banking_dwh.silver.dim_customer c
JOIN banking_dwh.silver.dim_account a ON c.customer_id = a.customer_id
LEFT JOIN transaction_summary ts ON a.account_id = ts.account_id
WHERE c.customer_name ILIKE regexp_replace(concat('%', replace(left(fn_balance_per_customer.customer_name, 100), '\\', '\\\\'), '%'), '%+', '%')
  AND lower(rtrim(a.status)) = 'active';
